<?php
namespace App\Services;
use App\Models\Booking;use App\Models\CheckoutPayment;use App\Models\Customer;use App\Models\HotelAgreement;use App\Models\HotelCharge;use App\Services\Accounting\AccountingExportService;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class HotelChargeService{
 public function generate(?int$organizationId=null,?int$customerId=null):int{$count=0;$q=HotelAgreement::where('status','active')->where('renews_on','<=',today());if($organizationId)$q->where('organization_id',$organizationId);if($customerId)$q->where('customer_id',$customerId);$q->with('customer')->chunkById(100,function($agreements)use(&$count){foreach($agreements as$a){DB::transaction(function()use($a,&$count){$locked=HotelAgreement::lockForUpdate()->find($a->id);while($locked&&$locked->status==='active'&&$locked->renews_on->lte(today())){$start=$locked->renews_on->copy();$end=$start->copy()->addMonthsNoOverflow(6);$charge=HotelCharge::firstOrCreate(['hotel_agreement_id'=>$locked->id,'period_starts_on'=>$start->toDateString()],['public_id'=>(string)Str::uuid(),'organization_id'=>$locked->organization_id,'customer_id'=>$locked->customer_id,'vehicle_id'=>$locked->vehicle_id,'period_ends_on'=>$end->toDateString(),'due_on'=>$start->toDateString(),'amount_cents'=>$locked->price_cents,'status'=>'open']);if($charge->wasRecentlyCreated)$count++;$locked->update(['renews_on'=>$end]);}});}});return$count;}
 public function payment(HotelCharge$charge):array{return DB::transaction(function()use($charge){$charge=HotelCharge::whereKey($charge->id)->lockForUpdate()->firstOrFail();abort_unless(in_array($charge->status,['open','attached'],true),409,'Kravet er allerede fakturert eller betalt.');$booking=$charge->booking;if(!$booking){$agreement=$charge->agreement;$booking=Booking::create(['public_id'=>(string)Str::uuid(),'organization_id'=>$charge->organization_id,'branch_id'=>$agreement->branch_id,'customer_id'=>$charge->customer_id,'vehicle_id'=>$charge->vehicle_id,'reference'=>'DH-'.now()->format('ymd').'-'.strtoupper(Str::random(5)),'service_name'=>'Dekkhotell · halvårsfornyelse','agreed_price_cents'=>$charge->amount_cents,'starts_at'=>now(),'ends_at'=>now(),'status'=>'completed','notes'=>'[HOTEL-CHARGE:'.$charge->id.'] Fakturagrunnlag uten verkstedtime.']);$charge->update(['booking_id'=>$booking->id]);}$invoice=app(AccountingExportService::class)->createFromBooking($booking,false);$charge->update(['invoice_export_id'=>$invoice->id,'status'=>'attached']);$plain=Str::random(64);$payment=CheckoutPayment::firstOrCreate(['booking_id'=>$booking->id,'invoice_export_id'=>$invoice->id],['public_id'=>(string)Str::uuid(),'organization_id'=>$charge->organization_id,'amount_cents'=>$invoice->total_cents,'terminal_reference'=>'DP-'.Str::upper(Str::random(18)),'lookup_token_hash'=>hash('sha256',$plain),'expires_at'=>now()->addDay()]);if(!$payment->wasRecentlyCreated){$plain=Str::random(64);$payment->update(['lookup_token_hash'=>hash('sha256',$plain),'expires_at'=>now()->addDay()]);}return[$payment,$plain];});}
}
